sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  var c = this;

  c.selectedYear = "";

  function atualizarIndicador() { // Mantenha ou renomeie (ex: 'atualizarValorApurado')
    c.server.get({ selectedYear: c.selectedYear }).then(function(response) {
      c.data = response.data;
      // Mantenha o console.log para debug, ajustando a mensagem
      console.log("Indicador Valor Apurado atualizado:", c.selectedYear, c.data); 
    });
  }

  // Recebe o ano vindo de outro widget
  $rootScope.$on('anoSelecionado', function(event, ano) {
    c.selectedYear = ano;
    atualizarIndicador();
  });

  // Primeira carga
  atualizarIndicador();
}

sp_widget.css:
.financial-widget {
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  margin-top: 4rem;
}

.indicator-block {
  text-align: center;
  padding: 0;
}

.indicator-header {
  background-color: #EBEDF1;
  color: #021770;
  font-weight: 400;
  padding: 8px 10px;
  font-size: 14px;
  border-bottom: 1px solid #C7C7C7;
}

.indicator-value {
  color: #021770;
  font-size: 32px;
  font-weight: 400;
  padding: 10px 10px 15px;
}

sp_widget.script:
(function() {

  input = input || {};
  var table = 'x_sded9_portal_t_0_programa_de_ajuste_fiscal';

  var selectedYear = input.selectedYear || "";

  // Se nenhum ano vier, pega o mais recente (a lógica de ano permanece)
  if (!selectedYear) {
    var g = new GlideRecord(table);
    g.orderByDesc('u_ano'); // Presume que a coluna de ano seja 'u_ano' como no original
    g.setLimit(1);
    g.query();
    if (g.next())
      selectedYear = g.getValue('u_ano');
  }

  data.selectedYear = selectedYear;

  data.indicator = {
    // Valor inicial/padrão
    value: '0', 
    // Label inicial/padrão: "Valor apurado" + ano (se existir)
    label: 'Valor apurado: ' + (selectedYear ? selectedYear : 'N/A')
  };

  var gr = new GlideRecord(table);

  if (selectedYear)
    gr.addQuery('u_ano', selectedYear); // Presume 'u_ano'

  gr.orderByDesc('sys_created_on');
  gr.setLimit(1);
  gr.query();

  if (gr.next()) {
    var anoReal = gr.getValue('u_ano');

    var valorApurado = gr.getValue('valor_apurado_endividamento');
    data.indicator.value = valorApurado + '%'; 
    data.indicator.label = 'Valor apurado ' + anoReal + ':';
    
    data.selectedYear = anoReal;
  }

})();
